module ShareTracker (\n    input clk,\n    input rst_n,\n    input start,\n    input in_valid,\n    input [8:0] in_day,\n    input [9:0] in_shares,\n    output reg out_valid,\n    output reg [8:0] out_day,\n    output reg [19:0] out_shares,\n    output reg done\n);\n    // State declarations (4 states)\n    localparam [1:0] IDLE       = 2'd0;\n    localparam [1:0] COLLECT    = 2'd1;\n    localparam [1:0] OUTPUT     = 2'd2;\n    localparam [1:0] FINISH     = 2'd3;\n    \n    reg [1:0] state;\n    reg [8:0] scan_day;          // 0-364\n    reg [9:0] collect_cycles;   // Timeout counter\n    reg output_started;         // Output sequence flag\n    reg prev_in_valid;          // Edge detection\n    \n    // Day memory (365 entries of 20-bit sums)\n    reg [19:0] day_sums [0:364];\n    \n    integer i;  // For-loop index\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            out_valid <= 1'b0;\n            out_day <= 9'd0;\n            out_shares <= 20'd0;\n            done <= 1'b0;\n            scan_day <= 9'd0;\n            collect_cycles <= 10'd0;\n            output_started <= 1'b0;\n            prev_in_valid <= 1'b0;\n            \n            // Initialize memory\n            for (i = 0; i < 365; i = i + 1) begin\n                day_sums[i] <= 20'd0;\n            end\n        end else begin\n            prev_in_valid <= in_valid;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    collect_cycles <= 10'd0;\n                    \n                    if (start) begin\n                        state <= COLLECT;\n                        // Clear memory on new start\n                        for (i = 0; i < 365; i = i + 1) begin\n                            day_sums[i] <= 20'd0;\n                        end\n                    end\n                end\n                \n                COLLECT: begin\n                    done <= 1'b0;\n                    out_valid <= 1'b0;\n                    collect_cycles <= collect_cycles + 10'd1;\n                    \n                    // Add valid records\n                    if (in_valid) begin\n                        if ((in_day >= 9'd1) && (in_day <= 9'd365)) begin\n                            day_sums[in_day - 9'd1] <= day_sums[in_day - 9'd1] + in_shares;\n                        end\n                    end\n                    \n                    // Exit conditions:\n                    // 1. Timeout (1000 cycles)\n                    // 2. Falling edge of in_valid with input seen\n                    if ((collect_cycles >= 10'd1000) || (prev_in_valid && !in_valid)) begin\n                        state <= OUTPUT;\n                        scan_day <= 9'd0;\n                        output_started <= 1'b0;\n                    end\n                end\n                \n                OUTPUT: begin\n                    if (!output_started) begin\n                        // Initial output setup\n                        output_started <= 1'b1;\n                        out_valid <= 1'b0;\n                        scan_day <= 9'd0;\n                    end else begin\n                        // Output non-zero entries\n                        if (day_sums[scan_day] != 20'd0) begin\n                            out_valid <= 1'b1;\n                            out_day <= scan_day + 9'd1;  // Convert to 1-365\n                            out_shares <= day_sums[scan_day];\n                        end else begin\n                            out_valid <= 1'b0;\n                        end\n\n                        // Advance to next day\n                        if (scan_day < 9'd364) begin\n                            scan_day <= scan_day + 9'd1;\n                        end else begin\n                            state <= FINISH;\n                        end\n                    end\n                end\n                \n                FINISH: begin\n                    out_valid <= 1'b0;\n                    done <= 1'b1;          // Assert done\n                    state <= IDLE;         // Return to idle\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule